def vertical_order(root):
    if not root:
        return []
    cols = defaultdict(list)  # column -> list of (row, val), in BFS discovery order
    queue = deque([(root, 0, 0)])  # node, row, col
    while queue:
        node, row, col = queue.popleft()
        cols[col].append((row, node.val))
        if node.left: queue.append((node.left, row + 1, col - 1))
        if node.right: queue.append((node.right, row + 1, col + 1))
    result = []
    for col in sorted(cols):
        # stable sort by row only — same-row ties keep BFS (left-to-right) discovery order
        result.append([val for row, val in sorted(cols[col], key=lambda p: p[0])])
    return result
```

Using BFS (not DFS) for discovery order matters here: it guarantees that within the same (row, column) — a genuine tie — nodes are recorded left-to-right, which is the conventional tie-breaking rule this problem expects.
